    db = get_db()
    fields = []
    values = []

    if name is not None:
        fields.append("name = ?")
        values.append(name)
    if color is not None:
        fields.append("color = ?")
        values.append(color)

    if not fields:
        return False

    values.append(category_id)
    db.execute(
        f"UPDATE categories SET {', '.join(fields)} WHERE id = ?", values
    )
    db.commit()
    return True


